  { img: 'rai-erupcao-vesuvio', leg: 'AI-generated illustration. Eruption of Vesuvius over Pompeii, AD 79: artistic interpretation.' },
  { img: 'rai-coluna-trajano', leg: 'Trajan’s Column, Rome (AD 113).' },
  { img: 'rai-muralha-adriano', leg: 'Hadrian’s Wall near Housesteads, Northumberland.' }
